export const renderSourcesPage = (): string => `<section class="explorer-page content-page" aria-labelledby="sources-title"><div class="explorer-heading"><p class="eyebrow">${t('nav.sources')}</p><h1 id="sources-title">${t('sources.title')}</h1><p>${t('sources.help')}</p></div>${renderEvidence(plannedSources)}</section>`;

const renderSavedCard = (item: SavedItem): string => `<article class="result-card workspace-card"><div><span class="entity-label">${t(`workspace.${item.kind}`)}</span><h3>${safe(item.label)}</h3><p>${safe(item.subtitle)}</p></div><div class="result-meta"><span>${safe(item.id)}</span><a class="text-link" href="#/${item.kind}/${encodeURIComponent(item.id)}">${t('explorer.details')} -&gt;</a></div></article>`;

export const renderWorkspacePage = (items: SavedItem[], history: HistoryEntry[], compare = false): string => `<section class="explorer-page content-page" aria-labelledby="workspace-title"><div class="explorer-heading"><p class="eyebrow">${compare ? t('workspace.compareEyebrow') : t('nav.saved')}</p><h1 id="workspace-title">${compare ? t('workspace.compareTitle') : t('workspace.title')}</h1><p>${compare ? t('workspace.compareHelp') : `${t('workspace.help')} <a class="text-link" href="#/compare">${t('workspace.compareTitle')} -&gt;</a>`}</p></div>${compare ? items.length >= 2 ? `<section class="data-panel compare-panel"><div class="panel-heading"><p class="eyebrow">${t('workspace.compareSelected')}</p><h2>${items.length}</h2></div><div class="table-wrap"><table><caption class="sr-only">${t('workspace.compareTitle')}</caption><thead><tr><th>${t('workspace.field')}</th>${items.slice(0, 4).map((item) => `<th>${safe(item.label)}</th>`).join('')}</tr></thead><tbody><tr><th>${t('workspace.kind')}</th>${items.slice(0, 4).map((item) => `<td>${t(`workspace.${item.kind}`)}</td>`).join('')}</tr><tr><th>${t('workspace.identifier')}</th>${items.slice(0, 4).map((item) => `<td>${safe(item.id)}</td>`).join('')}</tr><tr><th>${t('workspace.description')}</th>${items.slice(0, 4).map((item) => `<td>${safe(item.subtitle)}</td>`).join('')}</tr></tbody></table></div></section>` : `<p class="empty-state">${t('workspace.compareEmpty')}</p>` : `<section class="result-grid workspace-grid">${items.length ? items.map(renderSavedCard).join('') : `<p class="empty-state">${t('workspace.empty')}</p>`}</section><section class="data-panel history-panel"><div class="panel-heading"><p class="eyebrow">${t('workspace.history')}</p><h2>${history.length}</h2></div>${history.length ? `<div class="compact-list">${history.map((entry) => `<div><strong>${safe(entry.label)}</strong><a class="text-link" href="${safe(entry.href)}">${t('workspace.reopen')} -&gt;</a></div>`).join('')}</div>` : `<p class="empty-state">${t('workspace.noHistory')}</p>`}</section>`}</section>`;

export const renderWorkspaceSelectionPage = (items: SavedItem[], history: HistoryEntry[]): string => { const genes = items.filter((item) => item.kind === 'gene'); return `<section class="explorer-page content-page" aria-labelledby="workspace-title"><div class="explorer-heading"><p class="eyebrow">${t('nav.saved')}</p><h1 id="workspace-title">${t('workspace.title')}</h1><p>${t('workspace.help')} <a class="text-link" href="#/compare">${t('workspace.compareTitle')} -&gt;</a></p></div><form class="workspace-selection" id="compare-selection-form"><div class="result-grid workspace-grid">${genes.length ? genes.map((item) => `<label class="result-card workspace-card selectable-card"><input type="checkbox" name="gene" value="${safe(item.id)}"><span><span class="entity-label">${t('workspace.gene')}</span><strong>${safe(item.label)}</strong><small>${safe(item.subtitle)} · ${safe(item.id)}</small></span></label>`).join('') : `<p class="empty-state">${t('workspace.empty')}</p>`}</div><button class="action-button" type="submit">${t('workspace.compareSelected')}</button></form><section class="data-panel history-panel"><div class="panel-heading"><p class="eyebrow">${t('workspace.history')}</p><h2>${history.length}</h2></div>${history.length ? `<div class="compact-list">${history.map((entry) => `<div><strong>${safe(entry.label)}</strong><a class="text-link" href="${safe(entry.href)}">${t('workspace.reopen')} -&gt;</a></div>`).join('')}</div>` : `<p class="empty-state">${t('workspace.noHistory')}</p>`}</section></section>`; };

export const renderWorkspaceSelectionWithNotes = (items: SavedItem[], history: HistoryEntry[]): string => { const genes = items.filter((item) => item.kind === 'gene'); return `<section class="explorer-page content-page" aria-labelledby="workspace-title"><div class="explorer-heading"><p class="eyebrow">${t('nav.saved')}</p><h1 id="workspace-title">${t('workspace.title')}</h1><p>${t('workspace.help')} <a class="text-link" href="#/compare">${t('workspace.compareTitle')} -&gt;</a></p></div><form class="workspace-selection" id="compare-selection-form"><div class="result-grid workspace-grid">${genes.length ? genes.map((item) => `<div class="result-card workspace-card workspace-item"><label class="selectable-card"><input type="checkbox" name="gene" value="${safe(item.id)}"><span><span class="entity-label">${t('workspace.gene')}</span><strong>${safe(item.label)}</strong><small>${safe(item.subtitle)} · ${safe(item.id)}</small></span></label><label class="workspace-note-label" for="note-${safe(item.id)}">${t('workspace.note')}</label><textarea class="workspace-note" id="note-${safe(item.id)}" data-note-kind="gene" data-note-id="${safe(item.id)}" rows="3">${safe(getNote('gene', item.id))}</textarea><button class="action-button save-note" type="button" data-note-kind="gene" data-note-id="${safe(item.id)}">${t('workspace.saveNote')}</button></div>`).join('') : `<p class="empty-state">${t('workspace.empty')}</p>`}</div><button class="action-button" type="submit">${t('workspace.compareSelected')}</button></form><section class="data-panel history-panel"><div class="panel-heading"><p class="eyebrow">${t('workspace.history')}</p><h2>${history.length}</h2></div>${history.length ? `<div class="compact-list">${history.map((entry) => `<div><strong>${safe(entry.label)}</strong><a class="text-link" href="${safe(entry.href)}">${t('workspace.reopen')} -&gt;</a></div>`).join('')}</div>` : `<p class="empty-state">${t('workspace.noHistory')}</p>`}</section></section>`; };

const comparisonFields: Array<[string, (gene: Gene) => string | undefined]> = [
	['workspace.symbol', (gene) => gene.symbol], ['workspace.name', (gene) => gene.name], ['workspace.organism', (gene) => gene.organism], ['workspace.geneType', (gene) => gene.geneType], ['workspace.chromosome', (gene) => gene.chromosome],
	['workspace.mapLocation', (gene) => gene.mapLocation], ['workspace.assembly', (gene) => gene.location?.assembly], ['workspace.location', (gene) => gene.location ? `${gene.location.chromosome}:${gene.location.start ?? '?'}-${gene.location.end ?? '?'} ` : undefined], ['workspace.strand', (gene) => gene.location?.strand], ['workspace.recordStatus', (gene) => gene.recordStatus],
	['workspace.createdAt', (gene) => gene.createdAt], ['workspace.updatedAt', (gene) => gene.updatedAt], ['workspace.aliases', (gene) => gene.aliases.join(', ') || undefined], ['workspace.designations', (gene) => gene.designations?.join(', ')], ['workspace.genomicAccessions', (gene) => gene.genomicAccessions?.join(', ')],
];

export const renderGeneComparisonPage = (genes: Gene[]): string => `<section class="explorer-page content-page" aria-labelledby="comparison-title"><div class="explorer-heading"><p class="eyebrow">${t('workspace.compareEyebrow')}</p><h1 id="comparison-title">${t('workspace.compareTitle')}</h1><p>${t('workspace.compareHelp')}</p></div>${genes.length >= 4 ? `<section class="data-panel compare-panel"><div class="panel-heading"><p class="eyebrow">${t('workspace.compareSelected')}</p><h2>${genes.length}</h2></div><div class="table-wrap"><table class="comparison-table"><caption class="sr-only">${t('workspace.compareTitle')}</caption><thead><tr><th>${t('workspace.field')}</th>${genes.map((gene) => `<th>${safe(gene.symbol)}</th>`).join('')}</tr></thead><tbody>${comparisonFields.map(([key, getValue]) => `<tr><th>${t(key as Parameters<typeof t>[0])}</th>${genes.map((gene) => `<td>${safe(getValue(gene) ?? t('explorer.noData'))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>` : `<p class="empty-state">${t('workspace.compareMinimum')}</p>`}</section>`;

export const renderNotebookPage = (experiments: ExperimentRecord[]): string => `<section class="explorer-page content-page" aria-labelledby="notebook-title"><div class="explorer-heading"><p class="eyebrow">${t('nav.notebook')}</p><h1 id="notebook-title">${t('notebook.title')}</h1><p>${t('notebook.help')}</p></div><form class="lab-form notebook-form" id="notebook-entry-form"><label for="notebook-entry-title">${t('notebook.experimentTitle')}</label><input id="notebook-entry-title" name="title" required placeholder="${t('notebook.experimentTitlePlaceholder')}"><label for="notebook-entry-notes">${t('notebook.notes')}</label><textarea id="notebook-entry-notes" name="notes" rows="4" placeholder="${t('notebook.notesPlaceholder')}"></textarea><label for="notebook-entry-references">${t('notebook.references')}</label><textarea id="notebook-entry-references" name="references" rows="3" placeholder="${t('notebook.referencesPlaceholder')}"></textarea><label for="notebook-entry-data">${t('notebook.dataPoints')} (${t('notebook.max20')})</label><textarea id="notebook-entry-data" name="dataPoints" rows="8" placeholder="${t('notebook.dataPointsPlaceholder')}"></textarea><button class="action-button" type="submit">${t('notebook.createEntry')}</button></form><section class="result-grid notebook-grid">${experiments.length ? experiments.map((experiment) => `<article class="result-card experiment-card"><div><span class="entity-label">${safe(experiment.id)}</span><h3>${safe(experiment.title)}</h3><p>${t('notebook.created')}: ${safe(new Date(experiment.createdAt).toLocaleString())}</p>${experiment.analysis ? `<p>${t('lab.length')}: ${experiment.analysis.length} · ${t('lab.gc')}: ${experiment.analysis.gcPercentage}%${experiment.comparison ? ` · ${t('lab.comparison')}: ${experiment.comparison.identityPercentage}%` : ''}</p>` : ''}${experiment.references.length ? `<p>${t('notebook.references')}: ${experiment.references.map((reference) => safe(reference.label)).join(', ')}</p>` : ''}${experiment.dataPoints.length ? `<dl class="experiment-data">${experiment.dataPoints.map((point) => `<div><dt>${safe(point.label)}</dt><dd>${safe(point.value)}</dd></div>`).join('')}</dl>` : ''}${experiment.notes ? `<p class="experiment-notes">${safe(experiment.notes)}</p>` : ''}</div><div class="result-meta"><button class="action-button export-experiment" type="button" data-experiment-id="${safe(experiment.id)}">${t('notebook.export')}</button><button class="action-button delete-experiment" type="button" data-experiment-id="${safe(experiment.id)}">${t('notebook.delete')}</button></div></article>`).join('') : `<p class="empty-state">${t('notebook.empty')}</p>`}</section></section>`;
